insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'batesian', 'Batesian mimicry', 0, 'TERM:MIMICRY_TYPE:BATESIAN', 'protective', 'A palatable or harmless mimic resembles an unpalatable or dangerous model, deceiving predators that have learned to avoid the model.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'mullerian', 'Müllerian mimicry', 0, 'TERM:MIMICRY_TYPE:MULLERIAN', 'protective', 'Two or more defended species converge on a shared warning signal, spreading the cost of predator education among them.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'mertensian', 'Mertensian mimicry', 0, 'TERM:MIMICRY_TYPE:MERTENSIAN', 'protective', 'A more deadly species mimics a less dangerous one, hypothesised to arise when moderately venomous prey benefits from mimicking a milder model.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'aggressive', 'Aggressive mimicry', 0, 'TERM:MIMICRY_TYPE:AGGRESSIVE', null, 'A predator or parasite resembles a harmless or attractive signal-bearer to approach its own prey or hosts.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'reproductive', 'Reproductive mimicry', 0, 'TERM:MIMICRY_TYPE:REPRODUCTIVE', null, 'Mimicry that exploits the reproductive behaviour of another species, typically by imitating mates or reproductive resources.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'sexual_deception', 'Sexual deception', 0, 'TERM:MIMICRY_TYPE:SEXUAL_DECEPTION', 'reproductive', 'A mimic imitates the mate or mating signals of its receiver (often chemically and visually) to exploit their mating behaviour, as in pollinator sexual deception.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'brood', 'Brood mimicry', 0, 'TERM:MIMICRY_TYPE:BROOD', 'reproductive', 'A mimic exploits the parental care of another species, as in brood parasitism where the parasite''s offspring are reared by the host.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'egg', 'Egg mimicry', 0, 'TERM:MIMICRY_TYPE:EGG', 'brood', 'Mimicry of host eggs by a brood parasite''s egg, reducing rejection by the incubating host.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'social', 'Social mimicry', 0, 'TERM:MIMICRY_TYPE:SOCIAL', null, 'A mimic infiltrates a social species'' colony by imitating its members or their chemical identity.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'parasitic', 'Parasitic mimicry', 0, 'TERM:MIMICRY_TYPE:PARASITIC', 'social', 'A social parasite mimics its host species to gain acceptance inside the host colony or family unit.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'floral', 'Floral mimicry', 0, 'TERM:MIMICRY_TYPE:FLORAL', 'reproductive', 'A mimic imitates the flowers or floral signals of another species to attract pollinators without offering a reward, or a plant imitates insect signals.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'food_deception', 'Food deception', 0, 'TERM:MIMICRY_TYPE:FOOD_DECEPTION', 'reproductive', 'A mimic imitates food or food-related signals to exploit the foraging behaviour of receivers.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'protective', 'Protective mimicry', 0, 'TERM:MIMICRY_TYPE:PROTECTIVE', null, 'Mimicry in which the mimic gains protection from predation or aggression by resembling something the receiver avoids or ignores.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'automimicry', 'Automimicry', 0, 'TERM:MIMICRY_TYPE:AUTOMIMICRY', null, 'Within one species, palatable individuals or body parts resemble unpalatable ones, so the receiver cannot distinguish them.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'masquerade', 'Masquerade', 0, 'TERM:MIMICRY_TYPE:MASQUERADE', null, 'A mimic prevents recognition as prey by resembling an inedible object or organism of no interest to the receiver, rather than a warning signal.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'uncertain', 'Uncertain', 0, 'TERM:MIMICRY_TYPE:UNCERTAIN', null, 'The mimicry interpretation is unclear or contested — recorded with the dispute visible.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
insert into vocabulary_term (vocabulary, term, label, sort_order, public_id, parent_term, definition, version, status) values ('mimicry_type', 'other', 'Other', 0, 'TERM:MIMICRY_TYPE:OTHER', null, 'A mimicry pattern that does not fit the established categories.', '1.1', 'accepted') on conflict (vocabulary, term) do nothing;
