-- ==================== 001_initial.sql ====================

create table if not exists taxon (id uuid primary key default gen_random_uuid(), scientific_name text not null, canonical_name text, name_verbatim text not null, rank text, kingdom text, parent_taxon_id uuid references taxon(id), taxonomic_status text default 'accepted', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists reference (id uuid primary key default gen_random_uuid(), doi text, title text not null, authors text, year int, journal text, url text, citation_text text, created_at timestamptz default now());
create table if not exists mimicry_interaction (id uuid primary key default gen_random_uuid(), public_id text unique not null, mimic_taxon_id uuid references taxon(id), model_taxon_id uuid references taxon(id), receiver_description text, interaction_status text default 'candidate', knowledge_status text default 'reported', evidence_grade text default 'E0', evidence_grade_reason text, mimicry_summary text, model_resolution text, confidence numeric, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists evidence (id uuid primary key default gen_random_uuid(), interaction_id uuid not null references mimicry_interaction(id), reference_id uuid not null references reference(id), evidence_text text not null, page text, section text, figure text, evidence_grade text, source_method text default 'manual', created_at timestamptz default now());
create table if not exists audit_log (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, action text not null, old_value jsonb, new_value jsonb, changed_by uuid, reason text, timestamp timestamptz default now());
alter table taxon enable row level security; alter table reference enable row level security; alter table mimicry_interaction enable row level security; alter table evidence enable row level security;
drop policy if exists "public published interactions" on mimicry_interaction;
create policy "public published interactions" on mimicry_interaction for select using (interaction_status='published');


