create table if not exists taxon_synonym (id uuid primary key default gen_random_uuid(), taxon_id uuid not null references taxon(id) on delete cascade, synonym_name text not null, synonym_type text, source text, notes text, created_at timestamptz default now());
create table if not exists biological_entity (id uuid primary key default gen_random_uuid(), taxon_id uuid references taxon(id), entity_type text default 'unknown', label text, sex text, life_stage text, anatomical_structure text, signal_description text, notes text, created_at timestamptz default now());
create table if not exists vocabulary_term (id uuid primary key default gen_random_uuid(), vocabulary text not null, term text not null, label text, definition text, sort_order int default 0, unique (vocabulary, term));
alter table mimicry_interaction add column if not exists mimic_entity_id uuid references biological_entity(id), add column if not exists model_entity_id uuid references biological_entity(id), add column if not exists receiver_taxon_id uuid references taxon(id), add column if not exists receiver_resolution text, add column if not exists specific_model_identified boolean, add column if not exists geographic_overlap_status text, add column if not exists curator_notes text, add column if not exists created_by uuid, add column if not exists reviewed_by uuid, add column if not exists reviewed_at timestamptz, add column if not exists published_at timestamptz;
create table if not exists interaction_reference (interaction_id uuid not null references mimicry_interaction(id) on delete cascade, reference_id uuid not null references reference(id), created_at timestamptz default now(), primary key (interaction_id, reference_id));
create table if not exists interaction_geography (id uuid primary key default gen_random_uuid(), interaction_id uuid not null references mimicry_interaction(id) on delete cascade, country text, region text, locality text, latitude numeric, longitude numeric, geographic_scope text, sympatry_status text, geographic_evidence text, notes text, created_at timestamptz default now());
create table if not exists candidate (id uuid primary key default gen_random_uuid(), public_id text unique, proposed_mimic text, proposed_model text, proposed_receiver text, proposed_mimicry_type text, proposed_modality text, proposed_evidence_grade text, reference_id uuid references reference(id), evidence_text text, extraction_confidence numeric, extraction_model text, extraction_prompt_version text, extraction_timestamp timestamptz, raw_extraction jsonb, review_status text default 'pending', review_notes text, created_interaction_id uuid references mimicry_interaction(id), created_at timestamptz default now());
create table if not exists evolutionary_origin (id uuid primary key default gen_random_uuid(), public_id text unique not null, focal_mimic_clade_taxon_id uuid references taxon(id), model_taxon_id uuid references taxon(id), mimicry_type text, inferred_number_of_origins int, inference_method text, phylogeny_source text, analysis_version text, confidence numeric, notes text, created_at timestamptz default now());
create table if not exists interaction_origin (interaction_id uuid not null references mimicry_interaction(id) on delete cascade, origin_id uuid not null references evolutionary_origin(id) on delete cascade, primary key (interaction_id, origin_id));
